import "./alert.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type AlertTone = "default" | "success" | "warning" | "danger" | "info";

export type AlertProps = ComponentProps<"div"> & {
  tone?: AlertTone;
};

export type AlertTitleProps = ComponentProps<"div">;

export type AlertDescriptionProps = ComponentProps<"div">;

export function Alert({
  tone = "default",
  className,
  role,
  ...rest
}: AlertProps) {
  return (
    <div
      className={cx("ns-alert", className)}
      data-tone={tone}
      role={role ?? (tone === "danger" ? "alert" : "status")}
      {...rest}
    />
  );
}

export function AlertTitle({ className, ...rest }: AlertTitleProps) {
  return <div className={cx("ns-alert__title", className)} {...rest} />;
}

export function AlertDescription({ className, ...rest }: AlertDescriptionProps) {
  return <div className={cx("ns-alert__description", className)} {...rest} />;
}

@layer components {
  .ns-alert {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: var(--space-2, 0.31rem);
    box-sizing: border-box;
    width: 100%;
    padding: var(--space-5, 0.61rem) var(--space-6, 0.76rem);
    border: 1px solid var(--face-line, #626262);
    border-radius: var(--radius, 0.4rem);
    background: var(--face);
    background-clip: padding-box;
    color: var(--text-body, #444);
    font: inherit;
    line-height: var(--leading-tight, 1.25);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
  }

  .ns-alert__title {
    display: flex;
    align-items: center;
    gap: var(--space-3, 0.39rem);
    color: var(--on-key, #111);
    font-weight: var(--weight-medium, 500);
  }

  .ns-alert__title svg {
    width: 1em;
    height: 1em;
    flex-shrink: 0;
  }

  .ns-alert__description {
    color: var(--text-body, #444);
  }

  .ns-alert[data-tone="success"] {
    border-color: var(--success-line, color-mix(in srgb, var(--success, #2f6b3a) 42%, transparent));
    background: var(--success-surface, var(--face));
  }

  .ns-alert[data-tone="warning"] {
    border-color: var(--warning-line, color-mix(in srgb, var(--warning, #8a5a12) 42%, transparent));
    background: var(--warning-surface, var(--face));
  }

  .ns-alert[data-tone="danger"] {
    border-color: var(--error-line, color-mix(in srgb, var(--error, #8f3232) 42%, transparent));
    background: var(--error-surface, var(--face));
  }

  .ns-alert[data-tone="info"] {
    border-color: var(--info-line, color-mix(in srgb, var(--info, #2c4a6e) 42%, transparent));
    background: var(--info-surface, var(--face));
  }

  .ns-alert[data-tone="success"] .ns-alert__title {
    color: var(--success, #2f6b3a);
  }

  .ns-alert[data-tone="warning"] .ns-alert__title {
    color: var(--warning, #8a5a12);
  }

  .ns-alert[data-tone="danger"] .ns-alert__title {
    color: var(--error, #8f3232);
  }

  .ns-alert[data-tone="info"] .ns-alert__title {
    color: var(--info, #2c4a6e);
  }
}
